# This file was generated by AI

from pathlib import Path

import pytest

from bees_algorithm.configs import TSP_INSTANCES
from bees_algorithm.utils.exceptions import DataError
from bees_algorithm.utils.load_data import load_data


def _write_tsp(tmp_path: Path, filename: str, content: str) -> Path:
    path = tmp_path / filename
    path.write_text(content.strip() + "\n", encoding="utf-8")
    return path


@pytest.mark.parametrize(
    "instance_cfg",
    TSP_INSTANCES,
    ids=[inst.name for inst in TSP_INSTANCES],
)
def test_load_data_all_required_tsplib_instances(instance_cfg):
    coords = load_data(instance_cfg.path)
    assert len(coords) == instance_cfg.cities
    assert set(coords.keys()) == set(range(1, instance_cfg.cities + 1))
    for city_id, xy in coords.items():
        assert isinstance(city_id, int)
        assert isinstance(xy, list) and len(xy) == 2
        assert all(isinstance(v, float) for v in xy)


def test_load_data_valid_file(tmp_path: Path):
    tsp_file = _write_tsp(
        tmp_path,
        "mini3.tsp",
        """
        NAME : mini3
        TYPE : TSP
        DIMENSION : 3
        EDGE_WEIGHT_TYPE : EUC_2D
        NODE_COORD_SECTION
        1 0.0 0.0
        2 3.0 4.0
        3 6.0 8.0
        EOF
        """,
    )
    coords = load_data(str(tsp_file))
    assert coords == {
        1: [0.0, 0.0],
        2: [3.0, 4.0],
        3: [6.0, 8.0],
    }


@pytest.mark.parametrize(
    "missing_header",
    ["NAME", "TYPE", "DIMENSION", "EDGE_WEIGHT_TYPE"],
)
def test_load_data_missing_required_headers(tmp_path: Path, missing_header: str):
    lines = [
        "NAME: sample",
        "TYPE: TSP",
        "DIMENSION: 2",
        "EDGE_WEIGHT_TYPE: EUC_2D",
    ]
    kept = [line for line in lines if not line.startswith(missing_header)]
    content = "\n".join(kept + ["NODE_COORD_SECTION", "1 0 0", "2 1 1", "EOF"])
    tsp_file = _write_tsp(tmp_path, "sample.tsp", content)

    with pytest.raises(DataError, match=f"Missing header: {missing_header}"):
        load_data(str(tsp_file))


